CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE member_role AS ENUM ('owner','admin','editor','member','viewer'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text NOT NULL,display_name text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant_members(tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,role member_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,family_id uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,actor_user_id uuid REFERENCES users ON DELETE SET NULL,action text NOT NULL,resource_type text NOT NULL,resource_id text,request_id text NOT NULL,ip text,user_agent text,before_json jsonb,after_json jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_tenant_created_idx ON audit_logs(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS model_providers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,provider_type text NOT NULL CHECK(provider_type IN('openai','openai-compatible','mock')),name text NOT NULL,base_url text,encrypted_api_key text,enabled boolean NOT NULL DEFAULT true,config_json jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS model_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,provider_id uuid NOT NULL REFERENCES model_providers ON DELETE CASCADE,model_name text NOT NULL,capability_json jsonb NOT NULL DEFAULT '{}',input_price numeric(18,8) NOT NULL DEFAULT 0,output_price numeric(18,8) NOT NULL DEFAULT 0,enabled boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,provider_id,model_name));
CREATE TABLE IF NOT EXISTS usage_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE SET NULL,assistant_id uuid,provider_id uuid REFERENCES model_providers ON DELETE SET NULL,model_name text NOT NULL,input_tokens int NOT NULL DEFAULT 0,output_tokens int NOT NULL DEFAULT 0,embedding_tokens int NOT NULL DEFAULT 0,estimated_cost numeric(18,8) NOT NULL DEFAULT 0,latency_ms int NOT NULL,trace_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS usage_tenant_created_idx ON usage_records(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS knowledge_bases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,name text NOT NULL,description text NOT NULL DEFAULT '',embedding_model_config_id uuid REFERENCES model_configs ON DELETE SET NULL,chunk_config_json jsonb NOT NULL DEFAULT '{"chunkTokens":800,"overlapTokens":120,"minChunkTokens":80}',status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,knowledge_base_id uuid NOT NULL REFERENCES knowledge_bases ON DELETE CASCADE,file_name text NOT NULL,object_key text NOT NULL UNIQUE,mime_type text NOT NULL,file_size bigint NOT NULL,sha256 text NOT NULL,parse_status text NOT NULL DEFAULT 'queued',index_status text NOT NULL DEFAULT 'pending',version int NOT NULL DEFAULT 1,error_message text,processing_metrics_json jsonb NOT NULL DEFAULT '{}',created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,knowledge_base_id,sha256));
CREATE INDEX IF NOT EXISTS documents_tenant_kb_idx ON documents(tenant_id,knowledge_base_id);
CREATE TABLE IF NOT EXISTS document_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,knowledge_base_id uuid NOT NULL REFERENCES knowledge_bases ON DELETE CASCADE,document_id uuid NOT NULL REFERENCES documents ON DELETE CASCADE,index_version int NOT NULL,chunk_index int NOT NULL,content text NOT NULL,content_hash text NOT NULL,token_count int NOT NULL,page_number int,heading text,paragraph_number int,metadata_json jsonb NOT NULL DEFAULT '{}',embedding vector(1536),search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple',content)) STORED,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,index_version,content_hash));
CREATE INDEX IF NOT EXISTS chunks_tenant_kb_idx ON document_chunks(tenant_id,knowledge_base_id,index_version);
CREATE INDEX IF NOT EXISTS chunks_search_idx ON document_chunks USING gin(search_vector);
CREATE INDEX IF NOT EXISTS chunks_embedding_hnsw_idx ON document_chunks USING hnsw(embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS assistants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,name text NOT NULL,description text NOT NULL DEFAULT '',system_prompt text NOT NULL,model_config_id uuid NOT NULL REFERENCES model_configs,temperature real NOT NULL DEFAULT 0.2,max_output_tokens int NOT NULL DEFAULT 1024,retrieval_config_json jsonb NOT NULL DEFAULT '{"topK":8}',status text NOT NULL DEFAULT 'draft',published_version int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS assistant_knowledge_bases(tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,assistant_id uuid NOT NULL REFERENCES assistants ON DELETE CASCADE,knowledge_base_id uuid NOT NULL REFERENCES knowledge_bases ON DELETE CASCADE,PRIMARY KEY(assistant_id,knowledge_base_id));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,assistant_id uuid NOT NULL REFERENCES assistants ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,title text NOT NULL,status text NOT NULL DEFAULT 'active',summary text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE,role text NOT NULL CHECK(role IN('user','assistant','system')),content_json jsonb NOT NULL,token_usage_json jsonb NOT NULL DEFAULT '{}',model_name text,latency_ms int,trace_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_tenant_conversation_idx ON messages(tenant_id,conversation_id,created_at);
CREATE TABLE IF NOT EXISTS generation_cancellations(trace_id text PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN ALTER TABLE usage_records ADD CONSTRAINT usage_assistant_fk FOREIGN KEY(assistant_id) REFERENCES assistants ON DELETE SET NULL; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
